const e="royaume-uni",l=1,s={habitants:"les Britanniques",adjectif:"britannique",adjectifF:"britannique",devise:"Keep calm and carry on, mais en trois exemplaires signés",medaillon:"RU",chaineInfo:"UK TONIGHT",hymne:"Vive la Couronne et le thé tiède"},n={chambre:"Chambre des communes",chambreLong:"Chambre des communes du Royaume-Uni",chefGouvernement:"Premier ministre",chefEtat:"Monarque (rôle protocolaire)",passageForce:{label:"Whip à trois lignes",description:"Le Premier ministre transforme un vote ordinaire en vote de confiance et ordonne aux whips d'imposer la discipline de parti. Les récalcitrants risquent leur investiture et un thé froid.",news:"Whip à trois lignes sur {loi} : la majorité vote avec la ponctualité d'un horaire de train"},censure:{label:"Motion de défiance",description:"La Chambre des communes peut renverser le gouvernement à la majorité simple. Il faut pour cela convaincre des collègues de voter contre un parti qu'ils servent depuis trente ans.",news:"Motion de défiance déposée : l'opposition compte, recompte et soupire"},dissolution:{label:"Dissolution du Parlement",description:"Le Premier ministre demande au Monarque de dissoudre le Parlement et convoque des élections générales dans les cinq semaines. Les affiches de campagne sont imprimées avant l'annonce.",news:"Parlement dissous : le Monarque signe, les candidats sautent dans leurs bus"}},i={type:"legislatives",label:"Élections générales",intro:"Cinq semaines de campagne, des bus aux couleurs de partis, des chiens adoptés pour la photo et un débat où chacun dit « mon honorable adversaire » avec la voix de qui sort le couteau.",adversaires:[{id:"adv-uk-1",name:"Rupert Ashdown-Pell",parti:"Parti de l'Union Royale",style:"esquive",punchlines:["Je ne dis pas que c'est faux, je dis que ce n'est pas le moment.","Mon honorable adversaire a toujours raison, sauf sur les chiffres, les faits et la météo.","Nous avons un plan, dont les détails seront rendus publics après l'élection."],genre:"m"},{id:"adv-uk-2",name:"Imogen Fairweather",parti:"Parti Travailliste Réformé",style:"emotion",punchlines:["Dans ce pays, on attend un médecin plus longtemps qu'un colis.","Les gens ne veulent pas des slogans, ils veulent un lit à l'hôpital.","Je suis fille de mineur et petite-fille d'infirmière : mon arbre généalogique est mieux financé que le service de santé."],genre:"f"},{id:"adv-uk-3",name:"Clive Marchbanks",parti:"Mouvement Réformiste Populaire",style:"attaque",punchlines:["Le système est truqué, et je connais le tricheur.","L'establishment vous a pris pour des moutons, moi je vous prends pour des électeurs.","Un bus, une promesse : j'ai déjà choisi la couleur."],genre:"m"}],nuitElectorale:"La nuit électorale se déroule dans des gymnases municipaux où l'on compte les bulletins à la main, sous des néons clignotants, pendant qu'un présentateur dit « un résultat serré » toutes les quarante minutes."},t=[{id:"royaume-uni-plan-listes-attente",title:"Plan contre les listes d'attente hospitalières",domain:"sante",description:"Embaucher, rénover et réorganiser pour que « dans six mois » devienne « dans trois semaines ». Le service public national saluerait volontiers l'initiative si on lui laissait un créneau.",accroche:"La liste d'attente raccourcit, reste à trouver la file d'attente pour la consulter.",effects:{budget:-6,cohesion:2,popularite:2,assemblee:1},delayed:[{delay:4,effects:{popularite:1,cohesion:1},label:"Un rendez-vous obtenu avant la fin du mandat, c'est noté"}],groupStance:{"union-royale":.2,"travail-reforme":.8,"liberaux-democrates-b":.6,"nationalistes-nord":.5,"reforme-populaire":-.1,"verts-isles":.7},streetAnger:.1},{id:"royaume-uni-reforme-lords",title:"Réforme de la Chambre des lords",domain:"institutions",description:"Réduire le nombre de pairs nommés à vie et retirer les privilèges héréditaires. Les lords, qui votent à leur rythme, demandent un délai poli de trois siècles.",accroche:"Les lords gardent leurs sièges, mais devront désormais ôter le chapeau en séance.",effects:{assemblee:-4,popularite:1,cohesion:1},delayed:[{delay:4,effects:{assemblee:1,cohesion:1},label:"Le dernier siège héréditaire est remis en trois exemplaires"}],groupStance:{"union-royale":-.7,"travail-reforme":.5,"liberaux-democrates-b":.8,"nationalistes-nord":.4,"reforme-populaire":.2,"verts-isles":.8},streetAnger:.1},{id:"royaume-uni-devolution-renforcee",title:"Nouveau transfert de compétences aux nations",domain:"institutions",description:"Confier davantage de pouvoirs aux assemblées d'Édimbourg, de Cardiff et de Belfast. Le Parlement de Westminster envisage de s'en réjouir après consultation de son comité.",accroche:"Chaque nation gère ses affaires, et son thé, selon ses propres traditions bouillantes.",effects:{cohesion:2,assemblee:-2,popularite:-1},delayed:[{delay:4,effects:{cohesion:1,assemblee:1},label:"Les autonomistes remercient et réclament la suite"}],groupStance:{"union-royale":-.6,"travail-reforme":.4,"liberaux-democrates-b":.7,"nationalistes-nord":.9,"reforme-populaire":-.5,"verts-isles":.5},streetAnger:.1},{id:"royaume-uni-charte-presse",title:"Charte de déontologie de la presse à scandale",domain:"justice",description:"Créer un régulateur indépendant pour sanctionner le harcèlement et les fausses une. Les tabloïds invoquent la liberté de la presse, de préférence en gras 72.",accroche:"Une charte pour la presse à scandale, qui la lira surtout à la une.",effects:{cohesion:1,popularite:-3,assemblee:-1},delayed:[{delay:3,effects:{cohesion:1,popularite:1},label:"Les titres deviennent moins imaginatifs, à peine"}],groupStance:{"union-royale":-.3,"travail-reforme":.6,"liberaux-democrates-b":.7,"nationalistes-nord":.3,"reforme-populaire":-.9,"verts-isles":.4},streetAnger:.2},{id:"royaume-uni-plafond-energie",title:"Plafonnement de la facture d'énergie",domain:"energie",description:"Limiter la hausse des factures de gaz et d'électricité des ménages. Les fournisseurs promettent de faire preuve de compréhension dans leur prochaine hausse.",accroche:"La facture d'énergie est plafonnée, on garde le pull en laine par solidarité.",effects:{pouvoirAchat:3,budget:-4,popularite:2},delayed:[{delay:3,effects:{budget:-2},label:"L'État règle la différence aux fournisseurs"}],groupStance:{"union-royale":.2,"travail-reforme":.8,"liberaux-democrates-b":.5,"nationalistes-nord":.6,"reforme-populaire":.4,"verts-isles":-.2},streetAnger:0},{id:"royaume-uni-fluidite-manche",title:"Accord de fluidité douanière avec le continent",domain:"securite",description:"Simplifier les contrôles aux ports pour que les camions ne passent plus leur week-end dans une file d'attente. Le brouillard, lui, n'a pas été consulté.",accroche:"Passer la Manche sans file d'attente : le ferry en rêve, les mouettes aussi.",effects:{economie:3,international:3,popularite:-2,assemblee:-2},delayed:[{delay:4,effects:{economie:1,international:1},label:"Les camions franchissent la Manche avant le thé"}],groupStance:{"union-royale":-.1,"travail-reforme":.5,"liberaux-democrates-b":.9,"nationalistes-nord":.3,"reforme-populaire":-.9,"verts-isles":.2},streetAnger:.1},{id:"royaume-uni-frais-universitaires",title:"Réforme des frais d'inscription universitaires",domain:"education",description:"Faire payer plus ceux qui gagneront plus, en espérant qu'ils s'en souviennent au moment de voter. Les étudiants, eux, s'en souviennent déjà.",accroche:"Les frais baissent, les étudiants gardent leurs écharpes de collège pour l'élégance.",effects:{budget:2,popularite:-4,cohesion:-2,economie:1},delayed:[{delay:4,effects:{budget:1},label:"Les remboursements s'étalent jusqu'à la retraite"}],groupStance:{"union-royale":.5,"travail-reforme":-.8,"liberaux-democrates-b":-.2,"nationalistes-nord":-.5,"reforme-populaire":.2,"verts-isles":-.9},streetAnger:.5},{id:"royaume-uni-villes-nouvelles",title:"Programme de villes nouvelles",domain:"logement",description:"Construire dix villes nouvelles dans la campagne. Les habitants des campagnes actuelles découvrent d'un coup un attachement profond aux champs de colza.",accroche:"Des villes nouvelles, avec un rond-point d'honneur pour chaque quartier fondateur.",effects:{economie:2,popularite:1,ecologie:-3,budget:-4},delayed:[{delay:4,effects:{economie:1,pouvoirAchat:1},label:"La première rue ouvre, le premier rond-point la suit"}],groupStance:{"union-royale":-.2,"travail-reforme":.5,"liberaux-democrates-b":.4,"nationalistes-nord":.2,"reforme-populaire":0,"verts-isles":-.8},streetAnger:.3},{id:"royaume-uni-rail-public",title:"Renationalisation partielle du rail",domain:"ecologie",description:"Reprendre les lignes en main publique pour que le retard soit enfin imputé à quelqu'un. Les anciens exploitants regrettent déjà leurs retards d'autrefois.",accroche:"Le rail revient dans le giron public, avec les retards en héritage assumé.",effects:{cohesion:1,budget:-5,popularite:2,ecologie:1},delayed:[{delay:4,effects:{popularite:1,economie:1},label:"Un train arrive à l'heure : l'État s'en attribue le mérite"}],groupStance:{"union-royale":-.7,"travail-reforme":.9,"liberaux-democrates-b":.5,"nationalistes-nord":.6,"reforme-populaire":.1,"verts-isles":.7},streetAnger:.1},{id:"royaume-uni-pubs-minuit-et-demi",title:"Pubs ouverts jusqu'à minuit et demi",domain:"securite",description:"Allonger d'une heure et demie l'ouverture des pubs. La mesure vise à relancer l'économie nocturne, ou au moins à régler la dernière tournée à l'heure officielle.",accroche:"Une demi-heure de plus au pub, le temps qu'une pinte rédige sa démission.",effects:{popularite:2,securite:-2,economie:1},delayed:[{delay:3,effects:{securite:-1,popularite:1},label:"Quelques bagarres de plus, quelques pintes en plus"}],groupStance:{"union-royale":.5,"travail-reforme":.2,"liberaux-democrates-b":.3,"nationalistes-nord":.3,"reforme-populaire":.7,"verts-isles":-.4},streetAnger:0}],a=[{id:"royaume-uni-urgences-saturees",title:"Les urgences, salle d'attente nationale",category:"sante",description:"Un patient attend douze heures sur une chaise en plastique et en profite pour lire l'intégralité du règlement intérieur. Les syndicats de soignants réclament des moyens, le ministère une patience supplémentaire.",weight:6,choices:[{id:"plan-hiver",label:"Plan d'urgence pour l'hiver",description:"Lits supplémentaires, bénévoles, primes de nuit.",effects:{budget:-5,cohesion:2,popularite:2},delayed:[{delay:3,effects:{popularite:1},label:"Les urgences désemplissent un mardi"}],news:"Plan hivernal annoncé : des lits sont ajoutés, les chaises restent"},{id:"reorganiser",label:"Réorganiser le parcours de soins",description:"Un guichet unique, un numéro, un questionnaire.",effects:{budget:-2,popularite:-1,cohesion:1},delayed:[{delay:4,effects:{cohesion:1,popularite:1},label:"Moins de monde dans les couloirs"}],news:"Parcours de soins réorganisé : le formulaire d'accueil tient sur trois pages"},{id:"privatiser-lits",label:"Acheter des lits au privé",description:"Sous-traiter l'attente à des cliniques confortables.",effects:{budget:-4,popularite:1,cohesion:-3},news:"Des lits privés pour le public : la cohésion souffre, les files diminuent"}]},{id:"royaume-uni-brouillard-manche",title:"Brouillard sur la Manche",category:"economie",description:"Un brouillard épais immobilise ferries et camions pour quatre jours. Les rayons de supermarché se vident d'un seul coup de manière symbolique, et les ministres rappellent qu'il n'y a « aucune pénurie, seulement des étagères sobres ».",weight:4,minTurn:2,choices:[{id:"pont-aerien",label:"Organiser un pont aérien",description:"Approvisionner les villes par avion, malgré la facture.",effects:{budget:-5,economie:1,popularite:1},news:"Pont aérien : les clémentines arrivent par la voie des airs"},{id:"negocier-continent",label:"Négocier un couloir logistique avec le continent",description:"Un accord technique, signé dans la brume.",effects:{international:2,economie:1,budget:-2},delayed:[{delay:3,effects:{economie:1,international:1},label:"Les camions retrouvent leur route"}],news:"Couloir logistique négocié : la brume ne parle pas diplomatie"},{id:"rassurer-rayons",label:"Rassurer sans rien changer",description:"Demander aux Britanniques de rester calmes et de garder leur thé.",effects:{popularite:-2,cohesion:1},news:"« Restez calmes » : le gouvernement diffuse un message de trois mots"}]},{id:"royaume-uni-une-du-tabloid",title:"La une du tabloïd",category:"politique",description:"Un tabloïd titre en lettres rouges sur un supposé repas d'État « à quarante-huit euros la part de tarte ». Le secrétaire général de Downing Gate démissionne par pure précaution.",weight:5,minTurn:2,conditions:[{gauge:"popularite",op:"<",value:55}],choices:[{id:"assumer",label:"Assumer et expliquer le menu",description:"Détailler le prix de chaque ingrédient devant la presse.",effects:{popularite:-1,cohesion:1},news:"Le gouvernement détaille le prix de la tarte : la presse en demande une autre"},{id:"attaquer-presse",label:"Attaquer la presse à scandale",description:"Un discours sur les « pages roses de la désinformation ».",effects:{popularite:-4,assemblee:-1,cohesion:-1},news:"Le Premier ministre accuse les tabloïds : ils répondent en couleur"},{id:"sacrifier-conseiller",label:"Sacrifier un conseiller",description:"Une démission en échange d'un cycle d'actualité.",effects:{popularite:1,assemblee:-1},news:"Un conseiller démissionne, le tabloïd passe à autre chose"}]},{id:"royaume-uni-fronde-majorite",title:"Fronde dans la majorité",category:"politique",description:"Quarante députés de la majorité menacent de voter contre un texte, tout en jurant leur loyauté sur le sujet de la loyauté. Les « whips » conservent un carnet noir dont on murmure l'existence.",weight:5,minTurn:3,conditions:[{gauge:"assemblee",op:"<",value:48}],choices:[{id:"whip-trois-lignes",label:"Imposer un whip à trois lignes",description:"Interdiction absolue de voter autrement : la discipline sacrée.",effects:{assemblee:3,popularite:-2,cohesion:-1},news:"Whip à trois lignes : la majorité rentre dans le rang, en grinçant"},{id:"concessions",label:"Accepter des amendements de compromis",description:"Le texte devient plus modeste, donc plus voté.",effects:{assemblee:2,budget:-2,popularite:-1},news:"Compromis arraché in extremis : le texte, amaigri, passe"},{id:"vote-confiance-risque",label:"Poser un vote de confiance",description:"Jouer la survie du gouvernement sur un mardi.",effects:{assemblee:1,popularite:-3,international:-1},news:"Vote de confiance : le Premier ministre mise son bail sur un amendement"}]},{id:"royaume-uni-greve-du-rail",title:"Grève du rail, jour 14",category:"social",description:"Les syndicats ferroviaires prolongent leur mouvement pour la quatorzième journée consécutive. Les usagers inventent de nouvelles manières de ne pas arriver au bureau.",weight:5,minTurn:2,choices:[{id:"negocier-syndicats",label:"Reprendre la table de négociation",description:"Augmentation étalée, primes ciblées, communiqué convivial.",effects:{budget:-4,cohesion:1,popularite:1},delayed:[{delay:3,effects:{cohesion:1},label:"Un calme prudent règne sur les quais"}],news:"Accord sur les salaires du rail : les trains repartent, avec ponctualité modérée"},{id:"service-minimum",label:"Imposer un service minimum",description:"Exiger quelques trains, même mal fichus.",effects:{economie:1,popularite:-3,cohesion:-3},news:"Service minimum imposé : les syndicats parlent d'atteinte au droit de grève"},{id:"laisser-pourrir",label:"Attendre que la grève s'essouffle",description:"L'automne passera, la neige aussi.",effects:{economie:-3,popularite:-4,budget:1},news:"Grève : le gouvernement attend, les voyageurs aussi"}]},{id:"royaume-uni-pluie-inondations",title:"Il pleut, à nouveau",category:"climat",description:"Une succession de dépressions inonde plusieurs comtés, déplace des moutons et fait découvrir à des villages leur véritable altitude. Les assureurs lisent leur contrat avec une attention nouvelle.",weight:4,minTurn:2,choices:[{id:"fonds-inondations",label:"Débloquer un fonds d'urgence",description:"Pompes, sacs de sable et bottes en caoutchouc par lots.",effects:{budget:-4,popularite:2,cohesion:1},news:"Fonds d'urgence débloqué : les bottes en caoutchouc sont réquisitionnées"},{id:"plan-digues",label:"Lancer un plan de protection côtière",description:"Des digues, des marais restaurés et des cartes mises à jour.",effects:{budget:-5,ecologie:2,securite:1},delayed:[{delay:4,effects:{securite:1,ecologie:1},label:"Les villages ne rament plus"}],news:"Protection côtière : le pays se prépare à la prochaine averse"},{id:"assurance-privee",label:"Renvoyer vers les assureurs",description:"Chacun regarde son contrat, avec courage.",effects:{budget:1,popularite:-4,cohesion:-3},news:"Inondations : le gouvernement invite les sinistrés à relire leur contrat"}]},{id:"royaume-uni-referendum-nord",title:"Les autonomistes réclament un référendum",category:"politique",description:"Le Parti National du Nord brandit une pétition de 800 000 signatures et un calendrier prêt à l'emploi. Westminster répond qu'un « moment opportun » viendra, sans donner de date.",weight:4,minTurn:3,conditions:[{gauge:"cohesion",op:"<",value:55}],choices:[{id:"dialogue-constitutionnel",label:"Ouvrir un dialogue constitutionnel",description:"Un comité, une salle et des sandwichs.",effects:{cohesion:2,assemblee:-2,popularite:-1},delayed:[{delay:4,effects:{cohesion:1},label:"Les discussions se tiennent, c'est déjà beaucoup"}],news:"Dialogue constitutionnel : le premier sandwich est offert à tous"},{id:"refuser-net",label:"Refuser tout nouveau référendum",description:"Invoquer la volonté exprimée il y a quelques années.",effects:{assemblee:1,cohesion:-4,popularite:-2},news:"Londres refuse le référendum : le Nord a une pétition plus grande"},{id:"concessions-fiscales",label:"Accorder de nouveaux pouvoirs fiscaux",description:"Donner un peu pour garder beaucoup.",effects:{cohesion:1,budget:-3,assemblee:-1},news:"Nouveaux pouvoirs fiscaux : le Nord compte, Londres aussi"}]},{id:"royaume-uni-jubile-royal",title:"Jubilé : un beau jour de ciel bleu",category:"politique",kind:"evenement",description:"Une cérémonie royale attire des foules en drapeaux sous un improbable ciel bleu. Les observateurs notent que le pays se réconcilie, sans doute jusqu'à la prochaine averse.",weight:3,conditions:[{gauge:"popularite",op:">",value:40}],choices:[{id:"profiter-jubile",label:"Associer le gouvernement à la fête",description:"Parader discrètement sur le balcon.",effects:{popularite:2,cohesion:1,budget:-1},news:"Jubilé : le Premier ministre agite un petit drapeau avec dignité"},{id:"reste-discret",label:"Rester en retrait",description:"Laisser la fête appartenir à ceux qui en sont l'objet.",effects:{cohesion:1,popularite:1},news:"Jubilé : le gouvernement se tient en retrait, ce qui est remarqué"},{id:"annoncer-reformes",label:"Profiter du calme pour annoncer des réformes",description:"Une annonce sous la bannière de la fête.",effects:{assemblee:1,popularite:-2},news:"Réformes annoncées en plein jubilé : un choix de calendrier qui interroge"}]}],r=[{id:"royaume-uni-attente-raccourcie",title:"Raccourcir les listes d'attente",brief:"Gagnez 4 points de cohésion : l'attente n'a jamais été aussi bien partagée, il faut maintenant la réduire.",objective:{type:"gaugeGain",gauge:"cohesion",value:4},reward:{cohesion:2,popularite:1},news:"Listes d'attente : la file avance, cette fois dans le bon sens"},{id:"royaume-uni-majorite-tenue",title:"Garder la majorité en main",brief:"Un indice d'assemblée à 55 pour que les whips puissent enfin ranger leur carnet noir.",objective:{type:"gaugeAtLeast",gauge:"assemblee",value:55},reward:{assemblee:2,popularite:1},news:"Majorité : les whips sourient, ce qui inquiète"},{id:"royaume-uni-budget-sterling",title:"Présenter un budget honorable",brief:"Un budget à 50 : suffisant pour que le Chancelier de l'Échiquier cesse de se cacher derrière sa mallette rouge.",objective:{type:"gaugeAtLeast",gauge:"budget",value:50},reward:{budget:2,economie:1},news:"Budget : la mallette rouge est ouverte sans crainte"},{id:"royaume-uni-sans-voyant-rouge",title:"Un trimestre sans voyant rouge",brief:"Aucune jauge dans le rouge : l'équivalent national d'une journée sans pluie.",objective:{type:"noRedGauge"},reward:{popularite:1,cohesion:1},news:"Aucune jauge dans le rouge : une éclaircie de gestion"},{id:"royaume-uni-pupitre-du-perron",title:"Parler devant la porte noire",brief:"Une conférence de presse ce trimestre, debout derrière le pupitre du perron. La pluie est prévue, les questions aussi.",objective:{type:"pressHeld"},reward:{popularite:2,assemblee:1},news:"Conférence sur le perron : réponses brèves, parapluies nombreux",room:"presse",scene3d:"presse"}],o=JSON.parse('{"medias":["The Daily Kettle","Gazette de Westbury","Radio Crumpet","Northern Beacon TV"],"journalistes":[{"id":"royaume-uni-j-holloway","name":"Marguerite Holloway-Finch","media":"The Daily Kettle","style":"tenace : pose la même question quatre fois, avec un sourire de plus à chaque fois","genre":"f"},{"id":"royaume-uni-j-pennywhistle","name":"Alistair Pennywhistle","media":"Gazette de Westbury","style":"pointilleux : corrige la grammaire du dirigeant en direct","genre":"m"},{"id":"royaume-uni-j-thackeray","name":"Philippa Thackeray","media":"Radio Crumpet","style":"mielleuse : commence chaque question par un compliment qu’elle ne pense pas","genre":"f"},{"id":"royaume-uni-j-grimshaw","name":"Declan Grimshaw","media":"Northern Beacon TV","style":"bourru : ne croit qu’à ce qu’il voit tomber du ciel, c’est-à-dire de la pluie","genre":"m"},{"id":"royaume-uni-j-ravensworth","name":"Octavia Ravensworth","media":"The Daily Kettle","style":"mondaine : connaît tous les secrets de Westminster et les distille avec le thé","genre":"f"},{"id":"royaume-uni-j-bottomley","name":"Gethin Bottomley","media":"Radio Crumpet","style":"sceptique : arrive avec trois dossiers et en perd deux dans son sac","genre":"m"},{"id":"royaume-uni-j-lockwood","name":"Seren Lockwood","media":"Northern Beacon TV","style":"vive : parle à la vitesse d’un train en retard qui veut se rattraper","genre":"f"}],"questions":[{"id":"royaume-uni-q-pop-sondage-bas","theme":"popularite","condition":{"gauge":"popularite","op":"<","value":40},"text":"Chef du gouvernement, les sondages vous placent juste au-dessus du temps qu’il fait un mois de novembre. Vos conseillers cachent-ils les chiffres dans le tiroir du thé ?","answers":[{"tone":"franche","label":"Je les lis tous, je n’aime pas ce qu’ils disent, et je ne gouverne pas pour les aimer. Je gouverne pour que ça marche.","effects":{"popularite":4,"assemblee":-3},"delayed":[{"delay":3,"effects":{"popularite":-2},"label":"Les électeurs attendent encore que ça marche"}],"news":"Le Premier ministre reconnaît des sondages « franchement pas au beau fixe »"},{"tone":"langue-de-bois","label":"Les sondages sont un instantané, comme une photo de vacances sous la pluie : tout le monde se souvient du parapluie, pas du ciel.","effects":{"popularite":2,"economie":-2},"news":"Le Premier ministre compare les sondages à une photo de vacances pluvieuses"},{"tone":"offensive","label":"Les sondages, mon honorable ami, sont faits par des gens qui n’ont jamais ouvert un dossier de budget. Moi si, et je m’en excuse.","effects":{"popularite":5,"cohesion":-3,"international":-2},"delayed":[{"delay":2,"effects":{"assemblee":-3},"label":"Les instituts de sondage envisagent un recours collectif"}],"news":"Le Premier ministre s’en prend aux instituts de sondage"}]},{"id":"royaume-uni-q-pop-sondage-haut","theme":"popularite","condition":{"gauge":"popularite","op":">","value":68},"text":"Votre cote de popularité n’a jamais été aussi haute depuis la dernière victoire de l’équipe nationale en demi-finale. Cela ne vous inquiète pas ? Les Britanniques n’aiment-ils pas se retourner contre leurs héros ?","answers":[{"tone":"franche","label":"Si, ça m’inquiète. Chaque point de plus est un point de moins à reperdre en public, et j’ai peu de goût pour l’humiliation.","effects":{"popularite":3,"economie":-2},"news":"Le Premier ministre se méfie de sa propre popularité"},{"tone":"langue-de-bois","label":"Je me contente de servir le pays, avec modestie, sérieux et un thermos de thé dans le bureau.","effects":{"popularite":2,"cohesion":-2},"delayed":[{"delay":2,"effects":{"assemblee":-1},"label":"Le thermos de thé fait l’objet d’une question parlementaire"}],"news":"Le Premier ministre jure de rester modeste, thermos à l’appui"},{"tone":"offensive","label":"Les héros ne sont jamais renversés par l’opinion, seulement par leur propre équipe, et la mienne est bien sage.","effects":{"popularite":4,"assemblee":-4},"delayed":[{"delay":3,"effects":{"assemblee":-2,"cohesion":-1},"label":"Quelques députés de la majorité se sentent visés"}],"news":"Le Premier ministre défie ses propres bancs : « Sage, ma troupe »"}]},{"id":"royaume-uni-q-eco-croissance-faible","theme":"economie","condition":{"gauge":"economie","op":"<","value":42},"text":"La croissance est si molle qu’on la confond avec un scone de la veille. Quand le pays retrouvera-t-il un peu de relief économique ?","answers":[{"tone":"franche","label":"Pas avant dix-huit mois, et seulement si chacun accepte de dépenser un peu plus et de râler un peu moins.","effects":{"popularite":3,"pouvoirAchat":-2},"delayed":[{"delay":3,"effects":{"economie":2},"label":"Les entreprises commencent à y croire"}],"news":"Le Premier ministre promet la reprise dans dix-huit mois, sans le scone"},{"tone":"langue-de-bois","label":"Les fondamentaux sont solides, les perspectives sont encourageantes et le thé est servi, merci de patienter.","effects":{"economie":2,"popularite":-2},"news":"Le gouvernement juge l’économie « solide » et propose du thé"},{"tone":"offensive","label":"Je lance un plan d’investissement massif dans les usines et les ports, quitte à emprunter plus que je ne l’avoue.","effects":{"economie":5,"budget":-4,"international":2},"delayed":[{"delay":2,"effects":{"budget":-2},"label":"La facture arrive, avec une carte de visite"}],"news":"Le Premier ministre annonce un grand plan pour les usines et les ports"}]},{"id":"royaume-uni-q-eco-croissance-forte","theme":"economie","condition":{"gauge":"economie","op":">","value":65},"text":"L’économie ronronne comme un chat au coin du feu. Les opposants disent que c’est le calme avant la tempête. Devez-vous craindre un retour de bâton, ou croire à la chance ?","answers":[{"tone":"franche","label":"Il faut craindre, et préparer l’après. Une économie qui ronronne attire les promesses qu’on ne peut pas tenir.","effects":{"budget":3,"popularite":-2},"news":"Le Premier ministre appelle à ne pas gâcher la bonne conjoncture"},{"tone":"langue-de-bois","label":"La chance n’a rien à voir là-dedans. C’est du travail, de la rigueur et un excellent service de recherche d’alibis.","effects":{"popularite":4,"assemblee":-2},"delayed":[{"delay":2,"effects":{"cohesion":-2},"label":"Les syndicats réclament leur part de l’alibi"}],"news":"Le Premier ministre revendique le mérite de la bonne conjoncture"},{"tone":"offensive","label":"Si le bon temps dure, tant mieux ; s’il s’arrête, ce sera la faute du précédent gouvernement, comme toujours.","effects":{"popularite":3,"assemblee":-3,"international":-2},"delayed":[{"delay":3,"effects":{"popularite":-2},"label":"On ne rejoue pas la faute à l’ancien gouvernement trois fois de suite"}],"news":"Le Premier ministre blâme d’avance son prédécesseur pour la suite"}]},{"id":"royaume-uni-q-budget-deficit","theme":"budget","condition":{"gauge":"budget","op":"<","value":35},"text":"Le Trésor a lancé une alerte rouge : les caisses sont si vides qu’un écho y répond. Où allez-vous couper, et quel secteur crie en premier ?","answers":[{"tone":"franche","label":"Partout un peu, et surtout dans les dépenses de communication du gouvernement. On commence par la tour d’ivoire.","effects":{"budget":4,"popularite":-3},"delayed":[{"delay":2,"effects":{"assemblee":-2},"label":"La direction de la communication proteste par communiqué"}],"news":"Le Premier ministre coupe d’abord dans ses propres communiqués"},{"tone":"langue-de-bois","label":"Il faudra des efforts partagés, répartis équitablement entre ceux qui crient et ceux qui crient plus fort.","effects":{"budget":2,"cohesion":-2},"news":"Efforts « partagés » : le gouvernement distribue les cris équitablement"},{"tone":"offensive","label":"Je ne coupe rien : j’augmente les impôts des banques et des géants du numérique, qui ont des avocats mais pas d’électeurs.","effects":{"budget":5,"popularite":3,"economie":-4,"international":-3},"delayed":[{"delay":3,"effects":{"economie":-2},"label":"Les géants du numérique déménagent leur siège dans un cloud"}],"news":"Le Premier ministre taxe les banques et les géants du numérique"}]},{"id":"royaume-uni-q-budget-excedent","theme":"budget","condition":{"gauge":"budget","op":">","value":65},"text":"Fait rarissime, le budget est en bonne santé. Chacun veut sa part : la santé, les écoles, les routes, les pubs de village. Qui allez-vous décevoir le plus poliment ?","answers":[{"tone":"franche","label":"Je rembourse d’abord une partie de la dette. Ce n’est pas glamour, mais la dette, elle, ne prend jamais de vacances.","effects":{"budget":3,"popularite":-3},"news":"Le Premier ministre affecte l’excédent au remboursement de la dette"},{"tone":"langue-de-bois","label":"Un peu pour tout le monde, comme les parts de gâteau d’anniversaire : personne n’est content mais personne ne proteste.","effects":{"cohesion":3,"budget":-3},"delayed":[{"delay":2,"effects":{"pouvoirAchat":1},"label":"La part de gâteau est enfin visible à l’œil nu"}],"news":"Le gouvernement distribue l’excédent « en parts égales »"},{"tone":"offensive","label":"L’hôpital d’abord, sans discussion. La file d’attente est la seule chose de ce pays qui soit vraiment nationale.","effects":{"popularite":5,"budget":-5,"assemblee":-2},"delayed":[{"delay":3,"effects":{"cohesion":2},"label":"Les premiers lits supplémentaires apparaissent"}],"news":"Le Premier ministre fait de l’hôpital la grande priorité de l’excédent"}]},{"id":"royaume-uni-q-achat-facture","theme":"pouvoirAchat","condition":{"gauge":"pouvoirAchat","op":"<","value":40},"text":"Les ménages vous écrivent que leur facture de chauffage est plus élevée que leur loyer en 1998. Quand pourra-t-on remettre le chauffage sans prier ?","answers":[{"tone":"franche","label":"Pas cet hiver. Mais je verrouille les prix pour six mois et je prépare un vrai plan d’isolation des maisons.","effects":{"pouvoirAchat":4,"budget":-4},"delayed":[{"delay":3,"effects":{"ecologie":2,"budget":-1},"label":"Les premiers chantiers d’isolation démarrent, au grand étonnement de tous"}],"news":"Le Premier ministre verrouille les prix de l’énergie pour six mois"},{"tone":"langue-de-bois","label":"Les fournisseurs travaillent à des solutions, nous restons attentifs, et nous invitons les ménages à mettre un pull.","effects":{"pouvoirAchat":2,"popularite":-3},"news":"Le gouvernement invite les ménages à « mettre un pull »"},{"tone":"offensive","label":"Les fournisseurs ont fait des profits indécents. Je les convoque, je les fais payer, et on verra qui a froid.","effects":{"pouvoirAchat":5,"popularite":2,"economie":-4,"assemblee":-2},"delayed":[{"delay":2,"effects":{"economie":-2},"label":"Les fournisseurs menacent de moins investir"}],"news":"Le Premier ministre convoque les fournisseurs d’énergie"}]},{"id":"royaume-uni-q-achat-panier","theme":"pouvoirAchat","condition":{"gauge":"pouvoirAchat","op":"<","value":50},"text":"Le prix du panier de courses grimpe plus vite que la file devant le supermarché. Allez-vous plafonner le prix du pain, du lait et du paquet de biscuits au chocolat ?","answers":[{"tone":"franche","label":"Je plafonne le pain et le lait, pas les biscuits. Il faut bien qu’il reste un luxe en ce pays.","effects":{"pouvoirAchat":4,"economie":-3},"delayed":[{"delay":3,"effects":{"pouvoirAchat":-1},"label":"Des rayons vides pour le lait, selon quelques rumeurs"}],"news":"Le gouvernement plafonne le pain et le lait, épargne les biscuits"},{"tone":"langue-de-bois","label":"Une table ronde aura lieu avec les distributeurs, dans les semaines qui viennent, autour d’un thé que nous espérons non facturé.","effects":{"pouvoirAchat":2,"popularite":-2},"news":"Table ronde avec les supermarchés : le thé sera partagé"},{"tone":"offensive","label":"Vos biscuits et votre lait sont la dernière chose qui me préoccupe. Je préfère une baisse des taxes sur le travail.","effects":{"economie":4,"budget":-4,"popularite":-2},"delayed":[{"delay":2,"effects":{"economie":1,"pouvoirAchat":1},"label":"Le travail se félicite d’être, pour une fois, ménagé"}],"news":"Le Premier ministre préfère baisser les charges plutôt que plafonner les prix"}]},{"id":"royaume-uni-q-secu-ordre","theme":"securite","condition":{"gauge":"securite","op":"<","value":40},"text":"Des quartiers entiers disent ne plus se sentir en sécurité le soir. Est-ce que votre gouvernement a seulement un plan, ou seulement un communiqué ?","answers":[{"tone":"franche","label":"Les deux, mais le plan existe : plus de policiers de proximité, et des lumières allumées dans les rues, ce qui n’est pas rien.","effects":{"securite":5,"budget":-4},"delayed":[{"delay":3,"effects":{"securite":2,"popularite":1},"label":"Les rues s’éclairent, les habitants aussi"}],"news":"Le Premier ministre promet plus de policiers de proximité"},{"tone":"langue-de-bois","label":"La sécurité est une priorité absolue, avec les réserves d’usage et le calendrier habituel.","effects":{"securite":2,"popularite":-3},"news":"La sécurité devient « une priorité absolue » pour la quatrième fois"},{"tone":"offensive","label":"Je durcis les peines, j’étends les pouvoirs de fouille, et je ne m’excuse pas auprès de ceux qui aiment les débats.","effects":{"securite":6,"popularite":2,"cohesion":-5,"international":-2},"delayed":[{"delay":2,"effects":{"cohesion":-2,"assemblee":-2},"label":"Des manifestations de juristes devant le palais de justice"}],"news":"Le Premier ministre durcit les peines et élargit les fouilles"}]},{"id":"royaume-uni-q-cohesion-nations","theme":"cohesion","condition":{"gauge":"cohesion","op":"<","value":42},"text":"L’Écosse, le pays de Galles et l’Irlande du Nord disent que Westminster les écoute comme on écoute la météo : avec politesse et sans conséquence. Comment allez-vous recoller les morceaux ?","answers":[{"tone":"franche","label":"Je commence par venir les voir, avec un budget et un dossier, pas seulement un discours sur l’union.","effects":{"cohesion":5,"budget":-3},"delayed":[{"delay":3,"effects":{"cohesion":2,"assemblee":-1},"label":"Une visite à Cardiff qui se passe sans parapluie, c’est suspect"}],"news":"Le Premier ministre promet une tournée des capitales des nations"},{"tone":"langue-de-bois","label":"L’Union est une chose précieuse, que nous chérissons tous, y compris ceux qui n’y croient plus tout à fait.","effects":{"cohesion":2,"popularite":-2},"news":"Le Premier ministre déclare chérir l’Union, y compris ses opposants"},{"tone":"offensive","label":"Westminster ne se laissera pas dicter la loi par des assemblées de province. Le Parlement est souverain, c’est écrit quelque part.","effects":{"assemblee":4,"popularite":2,"cohesion":-6},"delayed":[{"delay":2,"effects":{"cohesion":-2,"international":-1},"label":"Un sondage donne plus d’indépendantistes que de gens qui aiment le thé"}],"news":"Le Premier ministre rappelle la souveraineté du Parlement"}]},{"id":"royaume-uni-q-cohesion-nord-sud","theme":"cohesion","condition":{"gauge":"cohesion","op":">","value":65},"text":"Entre le nord et le sud du pays, on se moque aimablement des accents, des repas et des prix de l’immobilier. Dans le fond, croyez-vous que ce pays a encore un destin commun ?","answers":[{"tone":"franche","label":"Oui, parce que personne ne sait mieux se moquer des autres que les gens qui se connaissent. C’est un lien, pas une fracture.","effects":{"cohesion":4,"pouvoirAchat":-2},"news":"Le Premier ministre voit dans la moquerie un « lien national »"},{"tone":"langue-de-bois","label":"Le gouvernement s’engage à réduire les écarts entre régions, avec un fonds de rattrapage doté de modestes ambitions.","effects":{"cohesion":3,"budget":-3,"popularite":-2},"delayed":[{"delay":4,"effects":{"economie":1},"label":"Une gare du nord est enfin rouverte, avec un café"}],"news":"Un fonds de rattrapage régional annoncé, sans date précise"},{"tone":"offensive","label":"Ceux qui se plaignent des accents ont tout simplement dû rater la dernière finale de football : on s’y entendait très bien.","effects":{"popularite":4,"cohesion":-3},"delayed":[{"delay":2,"effects":{"cohesion":1},"label":"Le foot reste la seule langue commune"}],"news":"Le Premier ministre convoque le football pour réconcilier le pays"}]},{"id":"royaume-uni-q-eco-climat-lent","theme":"ecologie","condition":{"gauge":"ecologie","op":"<","value":40},"text":"Vos objectifs climatiques ressemblent aux promesses d’un régime : toujours pour le mois prochain. Quand verra-t-on des éoliennes plus nombreuses que les bonnes résolutions ?","answers":[{"tone":"franche","label":"Dès cette année, avec un grand chantier de fermes éoliennes en mer. Les opposants au paysage devront s’habituer aux moulins.","effects":{"ecologie":5,"budget":-4,"assemblee":-2},"delayed":[{"delay":3,"effects":{"economie":2,"ecologie":1},"label":"Les turbines tournent et les factures commencent à baisser"}],"news":"Le Premier ministre lance un grand chantier d’éoliennes en mer"},{"tone":"langue-de-bois","label":"Nous sommes pleinement engagés, nous travaillons sur le sujet, et l’engagement est dans le calendrier, quelque part.","effects":{"ecologie":2,"international":-3},"news":"Le gouvernement est « pleinement engagé », selon son calendrier"},{"tone":"offensive","label":"Les promesses de régime, ce sont celles de l’opposition. Nous, on investit, et le grand perdant sera le gaz importé.","effects":{"ecologie":4,"economie":2,"assemblee":-3,"popularite":-2},"delayed":[{"delay":2,"effects":{"pouvoirAchat":-2},"label":"Les prix de l’électricité réagissent avant la météo"}],"news":"Le Premier ministre mise sur l’énergie propre contre le gaz importé"}]},{"id":"royaume-uni-q-eco-climat-haut","theme":"ecologie","condition":{"gauge":"ecologie","op":">","value":65},"text":"Le pays se vante d’un air plus pur et de rivières propres. Mais des habitants se plaignent du prix de la transition. Qui paie, selon vous, le prix de l’air frais ?","answers":[{"tone":"franche","label":"Tout le monde, mais pas pareillement : les gros pollueurs plus que les autres, et c’est un principe que je ne négocie pas.","effects":{"ecologie":3,"cohesion":3,"economie":-3},"delayed":[{"delay":2,"effects":{"economie":-1},"label":"Quelques usines hésitent entre le vert et la facture"}],"news":"Le Premier ministre fait payer l’air pur aux gros pollueurs"},{"tone":"langue-de-bois","label":"L’air est gratuit, c’est ce qui le rend si précieux, et que personne ne songe à nous facturer l’inspiration.","effects":{"popularite":2,"ecologie":-2},"news":"Le Premier ministre rappelle que l’air est gratuit"},{"tone":"offensive","label":"Une taxe verte légère sur les voyages en avion, c’est tout. Je n’ai jamais vu un touriste fâché contre une cathédrale propre.","effects":{"ecologie":4,"budget":3,"economie":-3,"international":-2},"delayed":[{"delay":3,"effects":{"economie":-1},"label":"Les compagnies aériennes rédigent une lettre longue et polie"}],"news":"Taxe verte sur les vols : les compagnies déposent un courrier poli"}]},{"id":"royaume-uni-q-intl-isole","theme":"international","condition":{"gauge":"international","op":"<","value":45},"text":"Depuis que vous avez changé de relation avec le continent, certains disent que le pays navigue seul sur un petit bateau. Qui sont vos amis à l’étranger, aujourd’hui ?","answers":[{"tone":"franche","label":"Pour l’instant, plus de voisins que d’amis. Je veux reconstruire la confiance, un accord commercial à la fois.","effects":{"international":5,"economie":-2},"delayed":[{"delay":3,"effects":{"economie":2},"label":"Un accord sur le fromage et l’acier rapproche deux rivages"}],"news":"Le Premier ministre veut rebâtir la confiance, accord par accord"},{"tone":"langue-de-bois","label":"Nous entretenons des relations excellentes et diversifiées avec tous nos partenaires, ceux de loin comme ceux d’à côté.","effects":{"international":2,"popularite":-2},"news":"Le gouvernement entretient des relations « excellentes et diversifiées »"},{"tone":"offensive","label":"Notre meilleur ami est toujours celui qui nous invite à dîner. Pour le reste, on peut très bien se débrouiller seuls.","effects":{"popularite":4,"international":-5,"economie":-2},"delayed":[{"delay":2,"effects":{"international":-2},"label":"Plusieurs capitales étrangères annulent leur invitation à dîner"}],"news":"Le Premier ministre : « Notre meilleur ami nous invite à dîner »"}]},{"id":"royaume-uni-q-assemblee-fronde","theme":"assemblee","condition":{"gauge":"assemblee","op":"<","value":35},"text":"Une trentaine de députés de votre majorité menacent de voter contre votre prochain texte. Vous allez les convoquer au salon vert ou leur faire servir du thé tiède jusqu’à ce qu’ils cèdent ?","answers":[{"tone":"franche","label":"Je les reçois un par un, j’écoute leurs doléances, et je reviens avec un texte amendé qui ne les humilie pas.","effects":{"assemblee":5,"budget":-2},"delayed":[{"delay":3,"effects":{"assemblee":2},"label":"Le texte amendé passe sans cris, un fait presque inédit"}],"news":"Le Premier ministre reçoit les frondeurs un par un"},{"tone":"langue-de-bois","label":"La discipline de parti est une valeur importante, mais je suis certain que chacun fera un choix éclairé, y compris le mien.","effects":{"assemblee":2,"popularite":-3},"news":"Le Premier ministre compte sur le choix éclairé de ses députés"},{"tone":"offensive","label":"Ceux qui votent contre perdront leur investiture. Je compte les voix, et je compte aussi les noms.","effects":{"assemblee":4,"popularite":-2,"cohesion":-5},"delayed":[{"delay":2,"effects":{"assemblee":-3},"label":"Trois élus rejoignent l’opposition en quittant la salle"}],"news":"Le Premier ministre menace de retirer l’investiture aux frondeurs"}]},{"id":"royaume-uni-q-assemblee-confortable","theme":"assemblee","condition":{"gauge":"assemblee","op":">","value":68},"text":"Vous avez une majorité si confortable que l’opposition ne se donne plus la peine de poser des questions. Cela ne vous donne-t-il pas le sentiment de gouverner sans contre-pouvoir ?","answers":[{"tone":"franche","label":"Si, et c’est dangereux. J’encourage mes propres députés à contredire, parce qu’un gouvernement qui ne rencontre jamais d’obstacle tombe sur le premier.","effects":{"assemblee":-2,"popularite":3,"cohesion":3},"news":"Le Premier ministre encourage ses députés à le contredire"},{"tone":"langue-de-bois","label":"Le gouvernement respecte pleinement le pluralisme, la démocratie et les créneaux horaires de chacun.","effects":{"cohesion":2,"popularite":-2},"delayed":[{"delay":2,"effects":{"assemblee":1},"label":"Les créneaux de parole sont distribués avec une rigueur de chef de gare"}],"news":"Le gouvernement respecte « pleinement le pluralisme »"},{"tone":"offensive","label":"Une opposition silencieuse est une opposition qui a lu mon programme. Je prends cela pour un compliment.","effects":{"popularite":3,"assemblee":2,"cohesion":-4,"international":-2},"delayed":[{"delay":3,"effects":{"cohesion":-2},"label":"Une pétition pour la liberté d’interpeller circule sur les bancs"}],"news":"Le Premier ministre voit dans le silence de l’opposition un compliment"}]},{"id":"royaume-uni-q-crise-urgences","theme":"crise","crisisId":"royaume-uni-urgences-saturees","text":"Les urgences sont saturées ; des patients attendent douze heures dans des couloirs. Peut-on dire à un malade qu’il est « en bonne place dans la file » ?","answers":[{"tone":"franche","label":"Non, et j’en suis désolé. Je débloque des lits, du personnel et je fais payer le retard à ceux qui l’ont causé, y compris moi.","effects":{"popularite":5,"budget":-5},"delayed":[{"delay":3,"effects":{"cohesion":2},"label":"Un couloir se vide, symboliquement"}],"news":"Le Premier ministre s’excuse et débloque des lits aux urgences"},{"tone":"langue-de-bois","label":"Le système de santé reste un fleuron national, malgré les défis ponctuels et récurrents de l’hiver, de l’été, et des autres saisons.","effects":{"cohesion":2,"popularite":-3},"news":"Urgences saturées : le gouvernement parle de « défis ponctuels »"},{"tone":"offensive","label":"La pression est due à l’absence de réformes sérieuses depuis dix ans. Je mets les gestionnaires au pied du mur.","effects":{"popularite":3,"budget":3,"cohesion":-4,"assemblee":-2},"delayed":[{"delay":2,"effects":{"cohesion":-2},"label":"Les gestionnaires organisent un sit-in avec feuille de calcul"}],"news":"Urgences saturées : le Premier ministre met les gestionnaires au pied du mur"}]},{"id":"royaume-uni-q-crise-rail","theme":"crise","crisisId":"royaume-uni-greve-du-rail","text":"La grève du rail dure depuis deux semaines. Les trains sont aussi ponctuels que votre dernier ministre des transports. Allez-vous vous asseoir à la table ou attendre que les rails rouillent ?","answers":[{"tone":"franche","label":"Je m’assieds à la table, avec les syndicats et les opérateurs. Il faudra parler de salaires, de sécurité et de pauses thé.","effects":{"popularite":4,"cohesion":3,"budget":-5},"delayed":[{"delay":2,"effects":{"economie":2},"label":"Les trains reprennent, certains même à l’heure"}],"news":"Le Premier ministre ouvre les négociations avec les syndicats du rail"},{"tone":"langue-de-bois","label":"Le dialogue reste ouvert, la porte aussi, même si pour l’instant les trains, eux, ne le sont pas.","effects":{"cohesion":2,"popularite":-3},"news":"Grève du rail : le dialogue est ouvert, les trains moins"},{"tone":"offensive","label":"Il faut un service minimum garanti. On ne prend pas un pays en otage, surtout un lundi matin.","effects":{"economie":4,"popularite":2,"cohesion":-5,"assemblee":-2},"delayed":[{"delay":3,"effects":{"cohesion":-3},"label":"La grève est reconduite avec une chanson de piquet très entraînante"}],"news":"Le Premier ministre exige un service minimum garanti sur le rail"}]},{"id":"royaume-uni-q-crise-pluie","theme":"crise","crisisId":"royaume-uni-pluie-inondations","text":"Pour la quatrième fois ce trimestre, des villes sont sous l’eau et la météo promet « des averses, puis des averses ». Faut-il déplacer les villes ou apprendre à nager ?","answers":[{"tone":"franche","label":"Il faut construire des digues et revoir où l’on bâtit. J’investis, et tant pis si ça coûte plus que prévu.","effects":{"securite":4,"ecologie":3,"budget":-5},"delayed":[{"delay":3,"effects":{"popularite":2},"label":"Les premiers sacs de sable sont remplacés par de vraies digues"}],"news":"Le Premier ministre lance un grand plan contre les inondations"},{"tone":"langue-de-bois","label":"Nous suivons la situation heure par heure, comme la pluie, en espérant qu’elle finisse par comprendre le message.","effects":{"popularite":2,"securite":-3},"news":"Inondations : le gouvernement « suit la situation heure par heure »"},{"tone":"offensive","label":"L’eau, c’est la nature qui reprend ses droits. Que ceux qui ont voulu une maison avec vue sur le fleuve en assument la vue.","effects":{"budget":3,"popularite":2,"cohesion":-5,"securite":-2},"delayed":[{"delay":2,"effects":{"popularite":-3},"label":"Les habitants inondés publient un courrier rédigé avec soin"}],"news":"Le Premier ministre renvoie les riverains inondés à leur vue sur le fleuve"}]},{"id":"royaume-uni-q-crise-referendum","theme":"crise","crisisId":"royaume-uni-referendum-nord","text":"Les autonomistes du Nord réclament un référendum d’indépendance, avec une affiche très réussie. Allez-vous dire oui, non, ou « peut-être, après le thé » ?","answers":[{"tone":"franche","label":"Je ne ferme pas la porte, mais la décision se prendra avec respect, patience et un cadre légal clair, pour tout le monde.","effects":{"cohesion":4,"assemblee":-3},"delayed":[{"delay":3,"effects":{"cohesion":2,"international":1},"label":"Le Nord apprécie le ton, même sans la date"}],"news":"Le Premier ministre ne ferme pas la porte, mais pose un cadre"},{"tone":"langue-de-bois","label":"Le gouvernement a pris note de cette demande, qu’il étudiera avec sérieux, calme et un grand sens de l’apaisement.","effects":{"cohesion":2,"popularite":-2},"news":"Référendum du Nord : le gouvernement « a pris note »"},{"tone":"offensive","label":"Non. Un pays n’est pas un abonnement qu’on résilie. L’Union reste une et indivisible, et la porte est solide.","effects":{"assemblee":4,"popularite":3,"cohesion":-6},"delayed":[{"delay":2,"effects":{"cohesion":-3,"international":-1},"label":"Les affiches « Oui » se multiplient comme des petits pains"}],"news":"Le Premier ministre dit non au référendum du Nord"}]},{"id":"royaume-uni-q-crise-tabloid","theme":"crise","crisisId":"royaume-uni-une-du-tabloid","text":"Un tabloïd publie à la une un « gouvernement au bord de l’implosion », avec une photo de vous en train de bâiller. Qui bâillait, vous ou le pays ?","answers":[{"tone":"franche","label":"C’était moi, c’était une longue nuit de travail, et je ne vais pas m’excuser d’être un humain.","effects":{"popularite":4,"assemblee":-2},"news":"Le Premier ministre assume son bâillement à la une"},{"tone":"langue-de-bois","label":"La presse libre est le pilier de notre démocratie, y compris lorsqu’elle photographie les gens aux moments les moins flatteurs.","effects":{"international":2,"popularite":-2},"delayed":[{"delay":2,"effects":{"cohesion":1},"label":"Le pilier de la démocratie salue le geste avec une manchette"}],"news":"Le Premier ministre défend la presse, même pour un bâillement"},{"tone":"offensive","label":"Ce tabloïd s’intéresse à mes bâillements parce qu’il est incapable de lire mon budget. Qu’il le lise, et il bâillera aussi.","effects":{"popularite":5,"international":-3,"cohesion":-2},"delayed":[{"delay":3,"effects":{"popularite":-2},"label":"Le tabloïd consacre trois pages à la lecture du budget, par vengeance"}],"news":"Le Premier ministre ridiculise le tabloïd sur la lecture du budget"}]},{"id":"royaume-uni-q-crise-generique","theme":"crise","text":"Une catastrophe de plus s’ajoute à celles de la semaine. À partir de combien de crises un gouvernement peut-il, honnêtement, parler de « malchance » ?","answers":[{"tone":"franche","label":"Après la troisième, j’imagine. Nous y sommes. Je prends mes responsabilités et je demande qu’on les mesure, pas qu’on les commente.","effects":{"popularite":4,"assemblee":-3},"delayed":[{"delay":3,"effects":{"popularite":1},"label":"Un tableau de bord des responsabilités est publié, avec des couleurs"}],"news":"Le Premier ministre : « Après la troisième crise, ce n’est plus de la malchance »"},{"tone":"langue-de-bois","label":"La malchance n’existe pas ; il n’y a que des défis, que l’on relève avec méthode, résilience et un peu de thé.","effects":{"cohesion":2,"popularite":-3},"news":"Le gouvernement refuse le mot « malchance », préfère « défis »"},{"tone":"offensive","label":"Les crises sont l’œuvre de nos prédécesseurs. Moi, j’ai seulement hérité de leurs factures et de leur thé tiède.","effects":{"popularite":3,"assemblee":-3,"cohesion":-3},"delayed":[{"delay":2,"effects":{"assemblee":-2},"label":"Un ancien ministre répond par une tribune de quatre mille mots"}],"news":"Le Premier ministre renvoie la crise à ses prédécesseurs"}]},{"id":"royaume-uni-q-scandale-lobby","theme":"scandale","text":"Un lobbyiste a invité sept ministres à un dîner de gala, avec un menu à neuf plats et un amendement offert en dessert. Le dîner était-il gratuit pour l’électeur aussi ?","answers":[{"tone":"franche","label":"Non, et c’est inacceptable. J’ouvre une enquête indépendante, et les ministres présents rendront leurs invitations et leurs serviettes.","effects":{"popularite":5,"assemblee":-3},"delayed":[{"delay":3,"effects":{"international":1,"popularite":1},"label":"L’enquête indépendante commence par un dîner, par précaution"}],"news":"Le Premier ministre ouvre une enquête sur le dîner des lobbyistes"},{"tone":"langue-de-bois","label":"Tous les dîners ont été déclarés conformément au registre, qui sera mis à jour dès que nous aurons trouvé le stylo.","effects":{"assemblee":2,"popularite":-4},"news":"Dîner du lobbyiste : le registre sera mis à jour « dès que possible »"},{"tone":"offensive","label":"Les lobbyistes font partie de la démocratie. Ce que je regrette, c’est que le menu n’ait pas été plus patriotique.","effects":{"popularite":3,"international":-2,"cohesion":-4},"delayed":[{"delay":2,"effects":{"popularite":-3,"assemblee":-1},"label":"Un traiteur britannique réclame des excuses pour le menu"}],"news":"Le Premier ministre regrette que le menu du lobbyiste ne soit pas patriotique"}]},{"id":"royaume-uni-q-scandale-fuite","theme":"scandale","text":"Une note confidentielle sur le budget a fuité dans un tabloïd, avec des annotations au stylo vert. Qui, dans votre entourage, a la plume si fuyante ?","answers":[{"tone":"franche","label":"Je l’ignore, mais je le saurai. Et quel que soit le coupable, il rendra son stylo vert à la sortie.","effects":{"popularite":3,"assemblee":-3},"delayed":[{"delay":2,"effects":{"assemblee":1},"label":"Le stylo vert est retrouvé dans le tiroir du chef de cabinet"}],"news":"Fuite d’une note budgétaire : le Premier ministre promet de trouver le coupable"},{"tone":"langue-de-bois","label":"Une enquête interne est en cours, qui se conclura avec la sérénité et la discrétion qui nous caractérisent.","effects":{"assemblee":2,"popularite":-3},"news":"Fuite d’une note budgétaire : une enquête interne « sereine » est ouverte"},{"tone":"offensive","label":"La note a fuité parce qu’elle était trop honnête. Je ne licencie personne pour avoir dit la vérité, même en vert.","effects":{"popularite":5,"budget":-2,"assemblee":-3},"delayed":[{"delay":3,"effects":{"assemblee":-2},"label":"Les ministres sont priés de consulter leurs stylos"}],"news":"Le Premier ministre défend la fuite : « Trop honnête »"}]},{"id":"royaume-uni-q-scandale-cadeau","theme":"scandale","text":"Un ministre a accepté de son ami hôtelier un séjour de luxe dans les Cotswolds, « gratuit mais pas tout à fait ». Les scones étaient-ils sans arrière-pensée ?","answers":[{"tone":"franche","label":"Non, et le ministre a donné sa démission ce matin. Les amis, on les garde pour le dimanche, pas pour les marchés publics.","effects":{"popularite":5,"cohesion":2,"assemblee":-4},"delayed":[{"delay":2,"effects":{"assemblee":-1},"label":"Le ministre revient en dîner, mais cette fois, sur son propre compte"}],"news":"Cadeau de l’hôtelier : un ministre démissionne"},{"tone":"langue-de-bois","label":"Le ministre a déclaré le séjour, les scones et la vue ; la commission d’éthique les examinera en temps utile.","effects":{"assemblee":2,"popularite":-3},"news":"Séjour dans les Cotswolds : la commission d’éthique « examinera »"},{"tone":"offensive","label":"L’hospitalité britannique est une vertu nationale. Que le pays se rassure : le ministre ne s’est pas laissé acheter par un scone.","effects":{"popularite":3,"assemblee":2,"international":-3,"cohesion":-3},"delayed":[{"delay":3,"effects":{"popularite":-3},"label":"Un historien rappelle le prix d’un scone en 1923"}],"news":"Le Premier ministre défend l’hospitalité du ministre"}]},{"id":"royaume-uni-q-culture-the","theme":"popularite","text":"Dites-nous la vérité, chef du gouvernement : le lait avant ou après le thé ? Le pays attend votre réponse depuis plus longtemps que l’accord commercial.","answers":[{"tone":"franche","label":"Après. Toujours. Et j’y mets une conviction que vous ne m’avez jamais vue sur l’économie.","effects":{"popularite":5,"cohesion":-3},"delayed":[{"delay":2,"effects":{"cohesion":1},"label":"Les partisans du lait d’abord manifestent poliment"}],"news":"Le Premier ministre tranche : le lait après le thé"},{"tone":"langue-de-bois","label":"C’est une question de goût personnel, qui relève de la sphère privée et d’un vaste débat national sans fin.","effects":{"cohesion":2,"popularite":-2},"news":"Thé et lait : le Premier ministre botte en touche"},{"tone":"offensive","label":"Cette question est indigne de ce pays. Nous avons des listes d’attente, des factures, et vous me parlez de lait.","effects":{"popularite":4,"cohesion":-4,"international":-2},"delayed":[{"delay":3,"effects":{"popularite":-2},"label":"Les amateurs de thé demandent des excuses écrites"}],"news":"Le Premier ministre refuse de parler de lait et de thé"}]},{"id":"royaume-uni-q-culture-foot","theme":"cohesion","text":"L’équipe nationale a encore perdu aux tirs au but. Le pays pleure, les pubs aussi. Un Premier ministre peut-il consoler une nation qui perd avec tant d’élégance ?","answers":[{"tone":"franche","label":"Oui, en rappelant que perdre ensemble vaut mieux que gagner seul. Et en offrant une tournée dans tous les pubs.","effects":{"cohesion":5,"budget":-3},"delayed":[{"delay":2,"effects":{"popularite":1},"label":"La tournée est remboursée en grande partie par des promesses"}],"news":"Le Premier ministre offre une tournée virtuelle aux pubs du pays"},{"tone":"langue-de-bois","label":"Nous sommes fiers de nos joueurs, qui ont donné tout ce qu’ils avaient, y compris leurs nerfs et leur poteau droit.","effects":{"cohesion":2,"popularite":-2},"news":"Défaite aux tirs au but : le gouvernement se déclare « fier »"},{"tone":"offensive","label":"Il faut réformer la fédération, entraîner les tireurs de penalty comme on forme les ministres : sérieusement.","effects":{"popularite":3,"assemblee":-2,"cohesion":-3},"delayed":[{"delay":3,"effects":{"cohesion":-1},"label":"La fédération annonce un audit de plusieurs mois et de plusieurs sandwichs"}],"news":"Le Premier ministre veut réformer la fédération de football"}]},{"id":"royaume-uni-q-culture-queue","theme":"cohesion","text":"Les Britanniques adorent faire la queue. Un sondage dit même que 63 % ont fait la queue pour une file qui ne menait nulle part. Votre gouvernement encourage-t-il la patience nationale ?","answers":[{"tone":"franche","label":"Oui, et je vous le dis franchement : la patience est notre dernière ressource naturelle renouvelable.","effects":{"cohesion":4,"popularite":-2},"news":"Le Premier ministre : « La patience est notre ressource renouvelable »"},{"tone":"langue-de-bois","label":"La file d’attente est un pilier de la vie civique, que le gouvernement protège avec les moyens limités dont il dispose.","effects":{"cohesion":2,"budget":-2,"popularite":2},"delayed":[{"delay":3,"effects":{"cohesion":1},"label":"Des panneaux « Veuillez patienter » sont installés devant les ministères"}],"news":"Le gouvernement dit protéger la file d’attente, « pilier civique »"},{"tone":"offensive","label":"Je ne fais jamais la queue. Mon chauffeur la fait pour moi, et il est très patient.","effects":{"popularite":3,"cohesion":-5,"international":-2},"delayed":[{"delay":2,"effects":{"popularite":-3},"label":"Le chauffeur du Premier ministre demande un congé de patience"}],"news":"Le Premier ministre fait faire la queue à son chauffeur"}]},{"id":"royaume-uni-q-culture-meteo","theme":"international","text":"Les visiteurs étrangers vous reprochent le temps, la cuisine et la façon dont on s’excuse pour tout. Comment défendre l’image du pays sans présenter vos excuses ?","answers":[{"tone":"franche","label":"Je défends le temps, c’est une personnalité. La cuisine progresse. Et nous ne nous excuserons pas… enfin, pardon, peut-être un peu.","effects":{"international":5,"popularite":2,"cohesion":-2},"news":"Le Premier ministre défend le temps : « C’est une personnalité »"},{"tone":"langue-de-bois","label":"L’image du pays est excellente à l’étranger, et même meilleure à l’intérieur, selon des études confidentielles.","effects":{"international":2,"popularite":-2},"delayed":[{"delay":2,"effects":{"international":-1},"label":"Une étude confidentielle est enfin publiée, avec des réserves"}],"news":"Le gouvernement juge l’image du pays « excellente »"},{"tone":"offensive","label":"Ceux qui n’aiment pas notre météo n’ont qu’à rester chez eux. Nous, nous avons des parapluies de très bonne qualité.","effects":{"popularite":4,"international":-4,"economie":-2},"delayed":[{"delay":3,"effects":{"economie":-2},"label":"Le tourisme hôtelier note un recul de la fréquentation"}],"news":"Le Premier ministre aux touristes : « Restez chez vous »"}]},{"id":"royaume-uni-q-culture-monarque","theme":"international","text":"Le Monarque s’apprête à recevoir un chef d’État étranger avec trois calèches et un banquet de six services. Qui paie, qui s’occupe du placement, et qui se charge de ne pas faire de gaffe ?","answers":[{"tone":"franche","label":"Le gouvernement paie, évidemment. Le Monarque règne, je gère les finances et un excellent plan de table.","effects":{"international":5,"budget":-4},"delayed":[{"delay":3,"effects":{"international":1,"economie":1},"label":"Le banquet finit en contrat de turbines, entre deux services"}],"news":"Le Premier ministre finance la visite d’État : le plan de table est prêt"},{"tone":"langue-de-bois","label":"La Couronne est un symbole de continuité, et le placement des convives obéit à un protocole séculaire que nous ne commenterons pas.","effects":{"international":2,"popularite":-2},"news":"Visite d’État : le gouvernement ne commente pas le plan de table"},{"tone":"offensive","label":"Pour éviter les gaffes, j’interdirai les sujets dangereux : la météo, la cuisine, le football et la douane.","effects":{"popularite":4,"international":-3,"cohesion":-2},"delayed":[{"delay":2,"effects":{"international":-2},"label":"Le chef d’État étranger demande de quoi on pourra parler"}],"news":"Le Premier ministre interdit quatre sujets au banquet royal"}]},{"id":"royaume-uni-q-culture-pubs","theme":"popularite","text":"Vos pubs ferment l’un après l’autre : un tous les quatre jours selon un rapport. Un pays sans pub, est-ce encore un pays ?","answers":[{"tone":"franche","label":"Non. Je baisse les taxes sur les pubs de village et j’interdis qu’un seul ferme sans un vote du conseil.","effects":{"popularite":5,"budget":-4,"economie":-2},"delayed":[{"delay":3,"effects":{"cohesion":2},"label":"Les villages recommencent à se retrouver devant un verre"}],"news":"Le Premier ministre baisse les taxes sur les pubs de village"},{"tone":"langue-de-bois","label":"Le pub est un lieu de sociabilité essentiel, que le gouvernement soutient moralement et avec des encouragements.","effects":{"cohesion":2,"popularite":-2,"budget":2},"news":"Le gouvernement soutient les pubs « moralement et avec encouragements »"},{"tone":"offensive","label":"Si les pubs ferment, c’est que les gens boivent chez eux, et s’éclairent à la bougie pour économiser. C’est un choix.","effects":{"popularite":3,"budget":3,"cohesion":-5},"delayed":[{"delay":2,"effects":{"popularite":-3},"label":"Une coalition de cinq pubs annonce une assemblée générale"}],"news":"Le Premier ministre : « Les gens boivent chez eux, c’est un choix »"}]},{"id":"royaume-uni-q-culture-tech","theme":"international","text":"Le pays veut devenir un leader mondial de l’intelligence artificielle. Votre premier algorithme sait déjà faire la queue, mais pas encore calculer un budget. Pourquoi y croire ?","answers":[{"tone":"franche","label":"Parce que nous avons des universités, des chercheurs et un goût sincère pour le mot « stratégie ». Je finance les trois.","effects":{"international":4,"economie":3,"budget":-5},"delayed":[{"delay":3,"effects":{"economie":2,"international":1},"label":"Une jeune entreprise annonce vendre son algorithme de file d’attente"}],"news":"Le Premier ministre finance les universités et la recherche en IA"},{"tone":"langue-de-bois","label":"L’intelligence artificielle présente des opportunités et des risques, que nous examinons avec la prudence qui caractérise nos institutions.","effects":{"international":2,"popularite":-2},"news":"IA : le gouvernement parle d’« opportunités et de risques »"},{"tone":"offensive","label":"L’IA va supprimer des emplois, c’est vrai, mais elle supprimera d’abord les réunions. Voilà un progrès social.","effects":{"popularite":5,"economie":-3,"cohesion":-3},"delayed":[{"delay":2,"effects":{"cohesion":-2},"label":"Les syndicats exigent un algorithme de réunions limitées"}],"news":"Le Premier ministre : l’IA supprimera d’abord les réunions"}]}]}'),u={pays:e,version:1,textes:s,institutions:n,election:i,lois:t,crises:a,missions:r,presse:o};export{a as crises,u as default,i as election,n as institutions,t as lois,r as missions,e as pays,o as presse,s as textes,l as version};
